/**
 * TS≡Python byte-parity — compiled TS `buildAss` must reproduce every golden
 * `.ass` fixture generated by the Python port. Requires `npm run build` first.
 */

import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const { buildAss, getPreset } = await import(join(here, "..", "dist", "index.js"));

const goldenDir = join(here, "fixtures", "golden");
const words = JSON.parse(readFileSync(join(goldenDir, "words.json"), "utf8"));

let failures = 0;
let checked = 0;
for (const file of readdirSync(goldenDir).filter((f) => f.endsWith(".ass"))) {
  const preset = file.replace(/\.ass$/, "");
  const expected = readFileSync(join(goldenDir, file), "utf8");
  const got = buildAss(words, getPreset(preset));
  checked++;
  if (got !== expected) {
    failures++;
    console.error(`MISMATCH ${preset}.ass — TS output differs from Python golden`);
    // show first differing line
    const g = got.split("\n");
    const e = expected.split("\n");
    for (let i = 0; i < Math.max(g.length, e.length); i++) {
      if (g[i] !== e[i]) {
        console.error(`  line ${i + 1}:\n    TS: ${g[i]}\n    PY: ${e[i]}`);
        break;
      }
    }
  }
}

if (failures) {
  console.error(`\ncaption-engine parity FAILED: ${failures}/${checked} presets differ`);
  process.exit(1);
}
console.log(`caption-engine TS≡Python byte-parity OK (${checked} golden ASS presets)`);
